// Hongik University, Seoul campus (홍익대학교 서울캠퍼스, 서울 마포구 와우산 서쪽 비탈). Data is generated by scripts/campuses/hongik/build-package.mjs
// from the pilot (pilot/hongik-seoul, round 3): every model of active-models.json is destructible (no hospital, religious or hanok
// heritage building: the protected list is empty) - 27 buildings (홍문관·문헌관·제4공학관 detailed, the rest generic) + 4 bridges and the
// 대운동장 east stand / pergola, each its own destruction unit (bridges: no hazard tape); a baked ground with the pilot's ground look
// (src/campuses/hongik/ground-look.js), the planting of site/planting.mjs (same trees as the preview), the pilot's landscape/ models
// (landscape/landscape.mjs LANDSCAPE_FILES) and the non-destructible context (홍대 거리, 상수동, 와우산) fading into the haze.
// Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, HI_PLACEMENTS, HI_BUILDING_BASE, HI_HEIGHT_GRIDS, HI_HEIGHT_RANGE_M, HI_ENV_IDS, HI_ENV_MANIFEST_IDS, HI_LOOK, HI_DISPLAY, HI_PROVENANCE } from './data.js';
import { HI_FOOTPRINTS } from './footprints.js';
import { HI_PROTECTED } from './protected.js';
import { createHongikGroundLook } from './ground-look.js';

const MODEL_IDS = Object.freeze(HI_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/hongik/${file}`, import.meta.url).href;
const HAZE = HI_DISPLAY.haze, FADE = HI_DISPLAY.fade;

export const HONGIK = Object.freeze({
  id: 'hongik',
  meta: Object.freeze({ school: '홍익대학교', campus: '서울캠퍼스', short: '홍익대', modelNoun: '홍익대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: HI_PLACEMENTS,
  approvedCount: HI_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['hongmun', 'eng1', 'studentUnion', 'library', 'wawoo', 'munheon', 'standEast'].filter(id => MODEL_IDS.includes(id))),
  startBuildingId: 'hongmun',
  // Start (R3b, 2026-10-22): from the west (azimuth -1.35, camera west-south-west of the box) over the 대운동장 up the 와우산 slope:
  // 홍문관 on the left, the field, the slope cluster (제1공학관 · 와우관 · 학생회관 · 중앙도서관) and the wooded hilltop fill the upper
  // half, so a 390 px phone shows campus instead of the far 홍대 haze (haze band 30 % -> 15 % of the screen, review/r3b/after/start-*-390.png).
  // Box = E -80..70 m, N 124..216 m (world units: metres x 0.5, z = -N). R3 box: min [-58, 0, -107.5], max [40, 18, -25], azimuth -.2.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-40, 0, -108]), max: Object.freeze([35, 20, -62]), azimuth: -1.35 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: HI_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: HI_HEIGHT_GRIDS, buildingBase: HI_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30 + floor-link / photo level evidence, pilot/hongik-seoul); not a survey' }),
  environment: Object.freeze({ provenance: HI_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the place models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: HI_ENV_IDS, castShadow: Object.freeze([]), materialHook: createHongikGroundLook(HI_LOOK),
      // context.json display fade (preview.js FADE): campus clear to r0, the backdrop melts into the haze by r1
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, ...(FADE.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/hongik-seoul preview ground + planting + landscape + context, baked' }),
  }),
  // Protected: none at Hongik (every model destructible). Kept so a later pilot decision only needs a rebuild; the manifest exists only
  // when the list is not empty (src/main.js loads protected models only when models.length > 0).
  protected: Object.freeze({
    ...(HI_PROTECTED.length ? { manifestURL: asset('protected/manifest.json') } : {}),
    models: HI_PROTECTED,
  }),
  // Hazard tape around every destructible building and the stand (src/engine/hazard-tape.js): none on the bridges (rule 10.3) or the context.
  hazardTape: Object.freeze({ footprints: HI_FOOTPRINTS }),
  scene: Object.freeze({
    // preview.js: fog 1400..3200 m, hemisphere (#fff, #7d8a78, 1.35), sun #fff4e2 3.1 from (-260, 320, 220) to (0, 20, 40 EN) -> halved
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 700, far: 1600 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-130, 150, 130]), shadowSpan: 240 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: HI_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default HONGIK;
